    fun t(k: String): String = T[k]?.get(lang) ?: k

    /** name of a credit line (vehicle price / auction sale have no typed name) */
    fun ln(l: Line): String = when (l.key) { "veh" -> "🚚 " + t("due_veh"); "sale" -> "🔨 " + t("due_sale"); else -> l.name }
